SourceCode.Declaration:
public final class METTMSEngineDocumentTypeAttribute extends SysAttribute implements SysExtensionIAttribute
{
    METTMSSourceDocumentType documentType;

}

Method.Source:
/// <summary>
/// Creates a new instance of the attribute class
/// </summary>
public void new(METTMSSourceDocumentType _documentType)
{
    super();

    this.parmSourceDocumentType(_documentType);
}

public METTMSSourceDocumentType parmSourceDocumentType(METTMSSourceDocumentType _documentType = documentType)
{
    documentType = _documentType;

    return documentType;
}

/// <summary>
/// Returns the key used for storing cached data for this attribute.
/// </summary>
/// <returns>
/// A string representing the cache key.
/// </returns>
/// <remarks>
/// The key typically includes the class name and relevant members.
/// </remarks>
public str parmCacheKey()
{
    return classStr(METTMSEngineHeaderContract) + ';' + int2str(documentType);
}

/// <summary>
/// Determines if the same instance should be returned by the extension framework for a given extension.
/// </summary>
/// <returns>
/// true, if the same instance should be used; otherwise, false.
/// </returns>
/// <remarks>
/// When returning false, the SysExtension framework will create a new class instance for every invocation.
/// If the class is immutable, consider returning true to save memory and gain performance.
/// </remarks>
public boolean useSingleton()
{
    return false;
}
